#!/usr/bin/env bash
# Question 3: Autoscaler ${Q3_APP} not working. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl get apiservice v1beta1.metrics.k8s.io >/dev/null 2>&1 || {
  echo "this cluster image has no metrics-server: rebuild images with ./cka images build --force" >&2
  exit 1
}
kubectl create namespace "${Q3_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q3_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q3_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q3_APP}
  namespace: ${Q3_NS}
  labels: { app: ${Q3_APP} }
spec:
  replicas: 2
  selector:
    matchLabels: { app: ${Q3_APP} }
  template:
    metadata:
      labels: { app: ${Q3_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 50m, memory: 32Mi }
---
apiVersion: v1
kind: Service
metadata:
  name: ${Q3_APP}
  namespace: ${Q3_NS}
spec:
  selector: { app: ${Q3_APP} }
  ports: [{ port: 80 }]
---
apiVersion: autoscaling/v2
kind: HorizontalPodAutoscaler
metadata:
  name: ${Q3_APP}
  namespace: ${Q3_NS}
spec:
  scaleTargetRef: { apiVersion: apps/v1, kind: Deployment, name: ${Q3_APP} }
  minReplicas: 2
  maxReplicas: 6
  metrics:
    - type: Resource
      resource:
        name: cpu
        target: { type: Utilization, averageUtilization: 50 }
EOF
kubectl -n "${Q3_NS}" get deployment "${Q3_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q3.uid"
chmod 644 "/var/tmp/cka-q3.uid"

case "${Q3_FAULT}" in
  no-cpu-request)
    kubectl -n "${Q3_NS}" patch deployment "${Q3_APP}" --type=json -p '[{"op":"remove","path":"/spec/template/spec/containers/0/resources/requests/cpu"}]'
    ;;
  target-name)
    kubectl -n "${Q3_NS}" patch hpa "${Q3_APP}" --type=merge -p '{"spec":{"scaleTargetRef":{"name":"'"${Q3_APP}"'-v2"}}}'
    ;;
  target-kind)
    kubectl -n "${Q3_NS}" patch hpa "${Q3_APP}" --type=merge -p '{"spec":{"scaleTargetRef":{"kind":"StatefulSet"}}}'
    ;;
  max-one)
    kubectl -n "${Q3_NS}" patch hpa "${Q3_APP}" --type=merge -p '{"spec":{"minReplicas":1,"maxReplicas":1}}'
    ;;
  metrics-server-down)
    kubectl -n kube-system scale deployment/metrics-server --replicas=0
    kubectl -n kube-system wait --for=delete pod -l app.kubernetes.io/name=metrics-server --timeout=90s >/dev/null 2>&1 || true
    ;;
  metrics-apiservice)
    kubectl -n kube-system patch service metrics-server --type=json -p '[{"op":"replace","path":"/spec/ports/0/targetPort","value":8443}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q3_NS}" rollout status "deployment/${Q3_APP}" --timeout=120s >/dev/null 2>&1 || true
for _ in $(seq 1 45); do
  ready="$(kubectl -n "${Q3_NS}" get deployment "${Q3_APP}" -o jsonpath='{.status.readyReplicas}')"
  [[ "$(kubectl -n "${Q3_NS}" get hpa "${Q3_APP}" -o jsonpath='{.status.conditions[?(@.type=="ScalingActive")].status}' 2>/dev/null)" != True || "$ready" != [2-9]* ]] && break
  sleep 2
done
